-- CreateTableCREATE TABLE IF NOT EXISTS "MobilePushToken" (    "id" UUID NOT NULL DEFAULT gen_random_uuid(),    "userId" UUID NOT NULL,    "token" VARCHAR(512) NOT NULL,    "platform" VARCHAR(32) NOT NULL DEFAULT 'expo',    "deviceId" VARCHAR(255),    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    CONSTRAINT "MobilePushToken_pkey" PRIMARY KEY ("id"));-- CreateIndexCREATE UNIQUE INDEX IF NOT EXISTS "MobilePushToken_token_key" ON "MobilePushToken"("token");-- CreateIndexCREATE INDEX IF NOT EXISTS "MobilePushToken_userId_idx" ON "MobilePushToken"("userId");-- AddForeignKeyDO $$ BEGIN  IF NOT EXISTS (    SELECT 1 FROM pg_constraint WHERE conname = 'MobilePushToken_userId_fkey'  ) THEN    ALTER TABLE "MobilePushToken" ADD CONSTRAINT "MobilePushToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;  END IF;END $$;